// elemComplex returns element i of a storage slice as a complex128.
func elemComplex(s any, i int) complex128 {
	switch s := s.(type) {
	case []bool:
		return boolTo[complex128](s[i])
	case []int8:
		return complex128(complex(float64(s[i]), 0))
	case []int16:
		return complex128(complex(float64(s[i]), 0))
	case []int32:
		return complex128(complex(float64(s[i]), 0))
	case []int64:
		return complex128(complex(float64(s[i]), 0))
	case []uint8:
		return complex128(complex(float64(s[i]), 0))
	case []uint16:
		return complex128(complex(float64(s[i]), 0))
	case []uint32:
		return complex128(complex(float64(s[i]), 0))
	case []uint64:
		return complex128(complex(float64(s[i]), 0))
	case []float32:
		return complex128(complex(float64(s[i]), 0))
	case []float64:
		return complex128(complex(float64(s[i]), 0))
	case []complex64:
		return complex128(s[i])
	case []complex128:
		return s[i]
	}
	panic("ndarray: not a storage slice")
}

