// elemString formats element i of a storage slice as NumPy prints it.
func elemString(s any, i int) string {
	switch s := s.(type) {
	case []bool:
		if s[i] {
			return "true"
		}
		return "false"
	case []int8:
		return strconv.FormatInt(int64(s[i]), 10)
	case []int16:
		return strconv.FormatInt(int64(s[i]), 10)
	case []int32:
		return strconv.FormatInt(int64(s[i]), 10)
	case []int64:
		return strconv.FormatInt(int64(s[i]), 10)
	case []uint8:
		return strconv.FormatUint(uint64(s[i]), 10)
	case []uint16:
		return strconv.FormatUint(uint64(s[i]), 10)
	case []uint32:
		return strconv.FormatUint(uint64(s[i]), 10)
	case []uint64:
		return strconv.FormatUint(uint64(s[i]), 10)
	case []float32:
		return floatString(float64(s[i]), 32)
	case []float64:
		return floatString(float64(s[i]), 64)
	case []complex64:
		return complexString(complex128(s[i]), 32)
	case []complex128:
		return complexString(complex128(s[i]), 64)
	}
	panic("ndarray: not a storage slice")
}

// arithStore applies a binary operation to storage slices of one dtype.
func arithStore(op binCode, d, x, y any) {
	switch d := d.(type) {
	case []int8:
		binInt(op, d, x.([]int8), y.([]int8))
	case []int16:
		binInt(op, d, x.([]int16), y.([]int16))
	case []int32:
		binInt(op, d, x.([]int32), y.([]int32))
	case []int64:
		binInt(op, d, x.([]int64), y.([]int64))
	case []uint8:
		binInt(op, d, x.([]uint8), y.([]uint8))
	case []uint16:
		binInt(op, d, x.([]uint16), y.([]uint16))
	case []uint32:
		binInt(op, d, x.([]uint32), y.([]uint32))
	case []uint64:
		binInt(op, d, x.([]uint64), y.([]uint64))
	case []float32:
		binFloat(op, d, x.([]float32), y.([]float32))
	case []complex64:
		binComplex(op, d, x.([]complex64), y.([]complex64))
	case []complex128:
		binComplex(op, d, x.([]complex128), y.([]complex128))
	case []bool:
		binBool(op, d, x.([]bool), y.([]bool))
	}
}

