// accumulateStore sums or multiplies src along the middle axis of
// [outer][axisLen][inner] into dst; both have an accumulation dtype.
func accumulateStore(op reduceCode, dst, src any, outer, axisLen, inner int) {
	switch d := dst.(type) {
	case []int64:
		reduceNum(op, d, src.([]int64), outer, axisLen, inner)
	case []uint64:
		reduceNum(op, d, src.([]uint64), outer, axisLen, inner)
	case []float32:
		reduceNum(op, d, src.([]float32), outer, axisLen, inner)
	case []complex64:
		reduceNum(op, d, src.([]complex64), outer, axisLen, inner)
	case []complex128:
		reduceNum(op, d, src.([]complex128), outer, axisLen, inner)
	}
}

